import org.springframework.beans.factory.BeansException;
import org.springframework.beans.factory.NoSuchBeanDefinitionException;
import org.springframework.beans.factory.BeanCreationException;
import org.springframework.context.ApplicationContext;

public class SpringVariableAdvisor {
    // Assume applicationContext and other fields are properly initialized
    private ApplicationContext applicationContext;
    private static final String MODULE = "SpringVariableAdvisor";

    /**
     * Enhanced evaluate method with detailed error handling for Spring bean resolution.
     *
     * @param variable the variable name, expected to start with "spring:" for bean resolution
     * @return the resolved bean object, or null if the variable does not match the prefix
     * @throws ExfRuntimeException if bean retrieval fails, with a descriptive error message
     */
    public Object evaluate(String variable) {
        if (variable.startsWith("spring:")) {
            String beanName = variable.substring(7);
            try {
                return applicationContext.getBean(beanName);
            } catch (NoSuchBeanDefinitionException e) {
                String errorMsg = "Bean not found: " + variable;
                ExfTracker.error(MODULE, errorMsg, e);
                throw new ExfRuntimeException(errorMsg, e);
            } catch (BeanCreationException e) {
                String errorMsg = "Bean instantiation failed: " + variable;
                ExfTracker.error(MODULE, errorMsg, e);
                throw new ExfRuntimeException(errorMsg, e);
            } catch (BeansException e) {
                String errorMsg = "Error retrieving bean: " + variable;
                ExfTracker.error(MODULE, errorMsg, e);
                throw new ExfRuntimeException(errorMsg, e);
            }
        }
        return null;
    }
}
