package main

import (
	"compress/bzip2"
	"fmt"
	"io"
	"log"
	"os"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintf(os.Stderr, "Usage: %s <file1> [file2 ...]\n", os.Args[0])
		os.Exit(1)
	}

	for _, filename := range os.Args[1:] {
		if err := checkBzip2(filename); err != nil {
			if _, ok := err.(bzip2.StructuralError); ok {
				log.Printf("%s: StructuralError: %v", filename, err)
			} else {
				log.Printf("%s: Error: %v", filename, err)
			}
		} else {
			fmt.Printf("%s: OK\n", filename)
		}
	}
}

// checkBzip2 attempts to decompress the entire bzip2 file.
// It returns nil if decompression completes without errors,
// otherwise it returns the error encountered.
func checkBzip2(filename string) error {
	f, err := os.Open(filename)
	if err != nil {
		return err
	}
	defer f.Close()

	r := bzip2.NewReader(f)
	_, err = io.Copy(io.Discard, r)
	return err
}
