#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k, q;
    cin >> k >> q;

    // Min‑heap that always holds the k largest scores.
    // The smallest element in this heap is the k‑th largest overall.
    priority_queue<int, vector<int>, greater<int>> minHeap;

    // Read the initial k scores and build the heap.
